// Generate release notes from the commits between two tags.
//
//   node scripts/release/notes.mjs <tag-or-rev> [--from <tag>] [--repo <owner/name>] [--label <text>]
//
// The release workflow uses this only when `docs/RELEASE_NOTES_<tag>.md` does
// not exist: the repo mostly pushes directly to main instead of opening pull
// requests, so GitHub's auto-generated notes would collapse to a bare compare
// link. Reading the commit subjects gives something useful for free.
//
// The output is plain markdown, grouped by the conventional-commit type:
// feat → Features, fix → Fixes, perf → Performance, docs → Documentation,
// refactor → Refactoring, everything else (chore/ci/build/test/style) → Internal.
import { execFileSync } from "node:child_process";

const args = process.argv.slice(2);
const opt = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  if (i === -1) return fallback;
  const value = args[i + 1];
  args.splice(i, 2);
  return value ?? fallback;
};

const repo = opt("repo", process.env.GITHUB_REPOSITORY ?? "");
const from = opt("from", "");
const label = opt("label", "");
const toRef = args[0] ?? "HEAD";

const git = (argv, options = {}) =>
  execFileSync("git", argv, { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"], ...options }).trim();

/** Resolve a rev to a sha, or null when it does not exist (e.g. a tag not created yet). */
const resolve = (rev) => {
  try {
    return git(["rev-parse", "--verify", `${rev}^{commit}`]);
  } catch {
    return null;
  }
};

const target = resolve(toRef);
const head = resolve("HEAD");
const end = target ?? head;
if (!end) {
  console.error("[notes] no commits found");
  process.exit(1);
}
const title = label || toRef;

// The previous release tag reachable from the target commit. `describe` looks at
// the parent so that the target itself, when it is tagged, does not match.
let previous = from;
if (!previous) {
  try {
    previous = git(["describe", "--tags", "--abbrev=0", "--match", "v[0-9]*", `${end}^`]);
  } catch {
    previous = "";
  }
}

const range = previous ? `${previous}..${end}` : end;
const raw = git(["log", "--no-merges", "--format=%h%x1f%s%x1f%b%x1e", range]);

const GROUPS = [
  ["feat", "Features"],
  ["fix", "Fixes"],
  ["perf", "Performance"],
  ["docs", "Documentation"],
  ["refactor", "Refactoring"],
  ["other", "Other changes"],
  ["internal", "Internal"],
];
const order = new Map(GROUPS.map(([type], i) => [type, i]));
const buckets = new Map(GROUPS.map(([, heading]) => [heading, []]));

const classify = (subject) => {
  const match = /^([a-zA-Z]+)(?:\([^)]*\))?!?:\s*(.+)$/.exec(subject);
  if (!match) return { type: "other", text: subject };
  const type = match[1].toLowerCase();
  const text = match[2].trim();
  if (type === "feat" || type === "fix" || type === "perf" || type === "docs" || type === "refactor") {
    return { type, text };
  }
  return { type: "internal", text: `${type}: ${text}` };
};

let count = 0;
for (const record of raw.split("\x1e")) {
  const line = record.trim();
  if (!line) continue;
  const [sha, subject] = line.split("\x1f");
  if (!sha || !subject) continue;
  const { type, text } = classify(subject.trim());
  const heading = GROUPS.find(([t]) => t === type)[1];
  buckets.get(heading).push(`- ${text.replace(/\.$/, "")} (\`${sha}\`)`);
  count += 1;
}

const lines = [];
lines.push("<!-- generated by scripts/release/notes.mjs -->");
lines.push("");
lines.push(`## What changed (${count} commit${count === 1 ? "" : "s"})`);
for (const [type, heading] of GROUPS) {
  const items = buckets.get(heading);
  if (!items.length) continue;
  lines.push("");
  lines.push(`### ${heading}`);
  lines.push("");
  lines.push(...items);
}
if (!count) {
  lines.push("");
  lines.push("_No commits since the previous release._");
}

lines.push("");
if (repo && previous) {
  lines.push(`**Full changelog**: https://github.com/${repo}/compare/${previous}...${title}`);
} else if (repo) {
  lines.push(`**Full changelog**: https://github.com/${repo}/commits/${title}`);
}
lines.push("");
lines.push("> Generated from commit subjects. The bilingual, hand-written notes for");
lines.push(`> a release live in \`docs/RELEASE_NOTES_${title}.md\`.`);

process.stdout.write(`${lines.join("\n")}\n`);
